private fun statementLocation(
    statement: CommonInst,
    type: LocationType,
    relevantLocations: List<List<IntermediateLocation>>?
): IntermediateLocation? {
    if (TraceMessageBuilder.isGeneratedLocation(statement)) {
        val normalLocation = TraceMessageBuilder.tryResolveNormalGeneratedLocation(statement, relevantLocations)
            ?: return null
        return statementLocation(normalLocation, type, relevantLocations)
    }

    if (TraceMessageBuilder.isAbnormalLocation(statement)) {
        val normalLocation = TraceMessageBuilder.tryResolveNormalLocation(statement, relevantLocations)
            ?: return null
        return statementLocation(normalLocation, type, relevantLocations)
    }

    return IntermediateLocation(
        inst = statement,
        info = getInstructionInfo(statement),
        kind = "",
        message = null,
        type = type,
    )
}

private fun TracePathNode.unwrapBoundary(previous: TracePathNode?): TracePathNode {
    val statement = statement
    if (statement !is JMethodBoundaryInst) return this

    val instructions = statement.location.method.instList.instructions
    val previousStatement = previous?.statement?.takeIf { it.location.method == statement.location.method }
    val real = when (statement) {
        is JMethodEnterInst -> instructions.first()
        is JMethodExitNormalInst -> previousStatement as? JIRReturnInst
            ?: instructions.lastOrNull { it is JIRReturnInst }
        is JMethodExitExceptionalInst -> previousStatement as? JIRThrowInst
            ?: instructions.lastOrNull { it is JIRThrowInst }
    } ?: return this

    return copy(statement = real)
}

private fun List<TracePathNode>.unwrapBoundaries(): List<TracePathNode> {
    if (none { it.statement is JMethodBoundaryInst }) return this

}

fun isGeneratedLocation(stmt: CommonInst): Boolean {
    if (stmt is JMethodBoundaryInst) return true
    val locationMethod = stmt.location.method
    if (locationMethod is SpringGeneratedMethod) return true
    if (locationMethod is JIRLambdaMethod) return true
    if (locationMethod is JIREnrichedVirtualMethod) return true
    return false
}

fun tryResolveNormalGeneratedLocation(
    stmt: CommonInst,
    relevantLocations: List<List<IntermediateLocation>>?
): CommonInst? {
    if (stmt is JMethodEnterInst) return stmt.location.method.instList.first()
    if (stmt is JMethodExitNormalInst) {
        return tryResolveExitLocation(stmt, relevantLocations) { it is JIRReturnInst }
    }
    if (stmt is JMethodExitExceptionalInst) {
        return tryResolveExitLocation(stmt, relevantLocations) { it is JIRThrowInst }
    }
    if (stmt is JMethodBoundaryInst) return null
    val locationMethod = stmt.location.method
    if (locationMethod is JIRLambdaMethod) {
        val lambdaCreationLocation = (locationMethod.enclosingClass as JIRLambdaClass).lambdaLocation
            ?: return null
        return lambdaCreationLocation.method.instList.getOrNull(lambdaCreationLocation.index)
    }
    return null
}

